0323,"tvl_peak_date":"2024-12-09","tvl_current_usd":12511086,"tvl_drawdown_pct":43.67,"stablecoin_tvl_usd":null,"spot_dex_volume_24h_usd":13500961,"spot_dex_volume_30d_usd":318910555,"fees_24h_usd":48592,"fees_30d_usd":978009,"revenue_24h_usd":7320,"revenue_30d_usd":180307,"active_addresses_daily":null,"dev_activity_monthly":null,"tvl_concentration":null,"source_url":"https://api.llama.fi/v2/historicalChainTvl/Chainflip","fees_source_url":"https://api.llama.fi/overview/fees/Chainflip?dataType=dailyFees","revenue_source_url":"https://api.llama.fi/overview/fees/Chainflip?dataType=dailyRevenue","volume_source_url":"https://api.llama.fi/overview/dexs/Chainflip?dataType=dailyVolume","stablecoin_source_url":null,"methodology_note":"Chainflip is an appchain plus cross-chain vault system; DefiLlama TVL and DEX series should not be compared mechanically with general-purpose smart-contract L1s."},"team":{"as_of":"2026-07-29","founders":[{"name":"Simon Harman","role":"founder","prior":"founded Chainflip in 2020 as an independent project","source_url":"https://chainflip.io/lightpaper.pdf"}],"entity":"Chainflip Labs develops the protocol; validators run the State Chain and collectively control native-chain vaults, with governance and community councils retaining defined upgrade and emergency roles.","key_events":[{"date":"2020","type":"formation","description":"Simon Harman founded Chainflip.","source_url":"https://chainflip.io/lightpaper.pdf"},{"date":"2023-11-23","type":"tge","description":"FLIP launched after multiple private, equity, and public rounds.","source_url":"https://docs.chainflip.io/protocol/token-economics/genesis-token-economics-pre-2023"}],"regulatory_status":null},"narrative":{"as_of":"2026-07-29","purpose":"Provide native-asset cross-chain swaps without user-facing wrapped assets through validator-controlled vaults and a purpose-built JIT AMM.","positioning":"A Substrate-based cross-chain liquidity appchain competing with bridges, centralized exchanges, and native-swap networks.","competitors":[{"name":"THORChain","relationship":"native cross-chain swap competitor"},{"name":"centralized exchanges","relationship":"dominant cross-chain asset-conversion alternative"},{"name":"bridge aggregators","relationship":"cross-chain routing competitors and integration partners"}],"narrative_arc":"Chainflip moved from a cautious capped launch to broader chain coverage, lending, and substantial volume, while its core tradeoff remains capital-efficient native swaps versus threshold-vault custody risk.","media_sentiment":"mixed_positive"},"risk":{"as_of":"2026-07-29","exploits":[],"sanctions":{"flagged":false,"detail":"No chain-level designation is asserted; an archived exact-name SDN review remains an explicit gap."},"extraction_flags":["threshold_custody","validator_collusion","vault_implementation","governance_keys","token_security_ratio"],"audit_status":"The official documentation describes internal/external audits and bounties, but this dossier does not reconcile a complete current audit inventory.","risks":[{"type":"threshold_custody","detail":"A 100-of-150 authority threshold controls protocol vaults; users rely on an honest validator superminority and correct key-rotation software.","source_url":"https://docs.chainflip.io/protocol/governance-and-security"},{"type":"software_surface","detail":"State Chain accounting, AMM logic, witnessing, broadcasting, and several external-chain vault implementations create a larger fault surface than a single-chain AMM.","source_url":"https://docs.chainflip.io/protocol/governance-and-security"},{"type":"economic_security","detail":"Vault value can outrun staked FLIP security, so users must evaluate the changing security ratio rather than infer trustlessness from validator count alone.","source_url":"https://docs.chainflip.io/protocol/governance-and-security"}]},"synthesis":{"as_of":"2026-07-29","situation":"Chainflip processes $318.9M in 30-day volume against $12.5M TVL, while FLIP is 96.7% below its high and the protocol''s validator set collectively controls cross-chain vault liquidity.","postmortem":null,"why":"Chainflip persists because native BTC and other cross-chain routes solve a concrete user problem that single-chain AMMs cannot, while the State Chain makes routing, accounting, and liquidity programmable.","success_mechanism":"A purpose-built JIT AMM and threshold vaults reuse liquidity across native-chain routes; fees buy and burn FLIP while staking supplies economic security.","strategic_choices":["Build a dedicated Substrate appchain rather than deploy one-chain AMM contracts.","Use 100-of-150 threshold vault custody to support native assets without wrappers.","Launch with conservative caps before expanding chains, limits, and product verticals."],"unknowns":["Current validator identity, stake, delegation, and vault-value concentration.","A reconciled current audit inventory and coverage of every supported-chain vault.","How lending and additional chains change exploitable value relative to bonded FLIP."],"lessons_learned":["Native cross-chain UX moves bridge risk into validator, vault, and implementation risk rather than removing it.","Volume-to-TVL efficiency is meaningful only alongside settlement and custody exposure.","Token-market drawdown can coexist with growing protocol throughput."],"could_differ":"A wrapper-and-bridge design could reduce bespoke vault engineering but would lose the native-asset product thesis.","outlook":{"bull":"New routes and lending compound volume while validator security and FLIP value capture scale with vault exposure.","base":"Chainflip remains a useful native-swap niche with material but manageable threshold-custody risk.","bear":"A vault or authority failure overwhelms the security budget and damages integrations.","most_likely":"base"},"cause_tags":["native_cross_chain_swaps","appchain","threshold_vaults","jit_amm","economic_security"],"confidence":"high"}},"meta":{"dimension_completeness_pct":100,"data_co